// The text of an open file, with the conversions between byte offsets and the positions of the protocol (lines and UTF-16
// columns, counted from 0), and the token based searches that rename and go to definition use.
#pragma once
#include <cstdint>
#include <string>
#include <vector>
#include "tokens.hpp"

namespace blitz::lsp {
	struct position {
		uint32_t line      = 0;
		uint32_t character = 0; // UTF-16 code units
	};

	struct range {
		position start;
		position end;
	};

	/** A word of the source: Name, keyword or command, with its type character if it has one (`x%`, `name$`). */
	struct word {
		size_t      begin = 0; // Byte offset
		size_t      end   = 0;
		size_t      core_end = 0; // End of the name without the type character
		std::string name;      // Lower case, without the type character
		std::string text;      // As written
		size_t      token = 0; // Index in document::tokens
	};

	class document {
		public:
		std::string text;
		int         version = 0;

		explicit document(std::string source = std::string());
		void set_text(std::string source);

		position to_position(size_t offset) const;
		size_t   to_offset(position at) const;
		/** From the 1-based line and byte column of the compiler. */
		size_t   offset_of(uint64_t line, uint64_t column) const;
		range    to_range(size_t begin, size_t end) const;

		std::vector<tools::token> const& tokens() const { return _tokens; }
		std::vector<size_t> const&       starts() const { return _starts; }
		std::vector<word> const&         words() const { return _words; }

		/** The word that the offset is in or touches, or nullptr. */
		word const* word_at(size_t offset) const;

		/** The previous / next token that is not white space, from the token index (npos if none). */
		size_t previous_token(size_t token) const;
		size_t next_token(size_t token) const;

		/** What `Function`, `Type` ... this word is declared by, found from the tokens. */
		struct declaration {
			enum class kind { none, function, type, field, variable, constant, parameter, label, dim } what = kind::none;
			size_t begin = 0; // Byte offset of the name
			size_t end   = 0;
			size_t scope_begin = 0; // Function that it is local to (byte range), the whole file if it is global
			size_t scope_end   = 0;
		};

		/** The places that the declarations of a name are, in the order they are written in the file. */
		std::vector<declaration> declarations_of(std::string const& lower_name) const;

		/** The byte range of the function that the offset is in. false if it is in the main program. */
		bool function_at(size_t offset, size_t& begin, size_t& end, std::string* name = nullptr) const;

		/** What a rename of a name is: which kind of name it is and, for a variable, where it lives. */
		enum class what { field, type, function, label, variable };
		struct rename_plan {
			bool        ok = false;
			std::string why; // If not ok: why the word can't be renamed (keywords, commands of the runtime)
			what        role = what::variable;
			bool        local = false; // A Local or parameter, which only exists in one function of one file
			size_t      scope = 0;     // Start of that function
			std::string name;          // Lower case
		};

		/** The plan for renaming the word at the offset. A word that is declared in no file but written in a function of this
		 * one is a local, unless global_known says that a Global of that name exists in another file of the program. */
		rename_plan plan_rename(size_t offset, std::string const& builtin_hint = std::string(), bool global_known = false) const;

		/** Every place in this document that the plan changes, as byte ranges of the name (without the type character).
		 * origin: this is the document the plan was made in (locals are only changed there). */
		std::vector<std::pair<size_t, size_t>> apply_rename(rename_plan const& plan, bool origin, size_t origin_offset = 0) const;

		/** Convenience for one document: plan and apply. Empty and 'why' set if nothing can be renamed. */
		std::vector<std::pair<size_t, size_t>> rename_targets(size_t offset, std::string& why, std::string const& builtin_hint = std::string()) const;

		/** The files named by `Include "..."`, as written. */
		std::vector<std::string> includes() const;

		private:
		void build();

		std::vector<tools::token> _tokens;
		std::vector<size_t>       _offsets; // Start of each token
		std::vector<size_t>       _starts;  // Start of each line
		std::vector<word>         _words;
	};

	/** The edit that turns `from` into `to` with the least text: the common start and end are kept. */
	struct text_change {
		bool        any = false;
		size_t      begin = 0;
		size_t      end = 0; // In 'from'
		std::string replacement;
	};
	text_change minimal_change(std::string const& from, std::string const& to);

	std::string lower(std::string_view text);
} // namespace blitz::lsp
